module barrel_shifter (
    input [7:0] in,
    input [2:0] ctrl,
    output [7:0] out
);

    wire [7:0] s1, s2, s3;

    assign s1 = ctrl[2] ? {in[4:0], in[7:5]} : in;

    assign s2 = ctrl[1] ? {s1[6:0], s1[7:7]} : s1;

    assign s3 = ctrl[0] ? {s2[7:0], s2[0]} : s2;

    assign out = s3;
endmodule

module mux2X1( in0,in1,sel,out);
input in0,in1;
input sel;
output out;
assign out=(sel)?in1:in0;
endmodule
